// TF_CODING_ERROR: the Python binding raises it as Tf.ErrorException.
function _codingError(message: string): never {
  throw new TfError(message, TfDiagnosticType.CodingError)
}

// UsdPrim::GetParent(): the prim at the parent path (the pseudo-root for a
// root prim).
function _GetParent(prim: Prim): Prim | undefined {
  const slash = prim.path.lastIndexOf('/')
  return prim.getStage().getPrim(slash <= 0 ? '/' : prim.path.slice(0, slash))
}

// The identifier as it appears in apiSchemas, ahead of ":instanceName"
// (authorshipAPI.cpp:522-530).
function _GetSchemaIdentifier(): string {
  return AuthorshipAPI.typeName
}

// Instance name from e.g. "AuthorshipAPI:mymodel", or empty if not this
// schema (authorshipAPI.cpp:532-543).
function _GetInstanceNameFromAPISchemaName(apiSchemaName: string): string {
  const typeNameAndInstance = SchemaRegistry.getTypeNameAndInstance(apiSchemaName)
  if (typeNameAndInstance[0] !== _GetSchemaIdentifier()) {
    return ''
  }
  return typeNameAndInstance[1]
}

type _ListOpItemsField = 'explicitItems' | 'addedItems' | 'prependedItems' | 'appendedItems'

// SdfTokenListOp::GetItems(type) of an apiSchemas value, which is either an
// SdfListOp or its plain-value form.
function _GetListOpItems(listOp: unknown, field: _ListOpItemsField): readonly string[] {
  if (listOp instanceof SdfListOp) {
    const type = { explicitItems: 'explicit', addedItems: 'added', prependedItems: 'prepended', appendedItems: 'appended' }[field]
    return listOp.getItems(type as Parameters<typeof listOp.getItems>[0]) as string[]
  }
  return ((listOp as Record<string, unknown>)[field] as readonly string[] | undefined) ?? []
}

function _IsTokenListOp(value: unknown): boolean {
  return value instanceof SdfListOp ||
    (typeof value === 'object' && value !== null && !Array.isArray(value) &&
     ('explicitItems' in value || 'prependedItems' in value || 'appendedItems' in value ||
      'addedItems' in value || 'deletedItems' in value || 'orderedItems' in value))
}

// Appends the instance name of every record `spec` applies. Only scans
// apiSchemas, since a bare property name can't be split back into instance
// and base name reliably (authorshipAPI.cpp:545-581).
function _AppendInstanceNamesInSpec(spec: SdfSpec, instanceNames: string[]): void {
  if (!spec.hasInfo('apiSchemas')) {
    return
  }
  const value = spec.getInfo('apiSchemas')
  if (!_IsTokenListOp(value)) {
    return
  }

  // A token could appear in more than one list-op field, so dedup with a
  // set (std::set<TfToken>: sorted).
  const found = new Set<string>()

  // Scan every op that adds the schema, not just the applied result:
  // shadowed opinions are exactly what the diagnostics look for. Ordered
  // items only reorder, so they don't indicate presence.
  for (const listOpType of ['explicitItems', 'addedItems', 'prependedItems', 'appendedItems'] as const) {
    for (const apiSchemaName of _GetListOpItems(value, listOpType)) {
      const instanceName = _GetInstanceNameFromAPISchemaName(apiSchemaName)
      if (instanceName !== '') {
        found.add(instanceName)
      }
    }
  }

  instanceNames.push(...[...found].sort(_TokenCompare))
}

// UsdPrim::GetPrimStack(): the prim's specs, strongest first.
function _GetPrimStack(prim: Prim): Array<SdfSpec | undefined> {
  return prim.getStage().getPrimStack(prim.path).map((entry) =>
    Layer.find(entry.layerIdentifier)?.getObjectAtPath(entry.specPath))
}

// How many specs in `prim`'s prim stack apply each instance
// (authorshipAPI.cpp:583-599). std::map<TfToken, size_t>: key-sorted.
function _CountApplicationsInPrimStack(prim: Prim): Map<string, number> {
  const counts = new Map<string, number>()
  for (const spec of _GetPrimStack(prim)) {
    if (!spec) {
      continue
    }
    const instanceNames: string[] = []
    _AppendInstanceNamesInSpec(spec, instanceNames)
    for (const instanceName of instanceNames) {
      counts.set(instanceName, (counts.get(instanceName) ?? 0) + 1)
    }
  }
  return new Map([...counts].sort((a, b) => _TokenCompare(a[0], b[0])))
}

// authorshipAPI.cpp:601-609
function _AppendComposedRecordsForPrim(prim: Prim, result: AuthorshipAPI[]): void {
  for (const record of AuthorshipAPI.getAll(prim)) {
    result.push(record)
  }
}

// authorshipAPI.cpp:611-632
function _AppendShadowedRecordsForPrim(prim: Prim, result: AuthorshipAPI[]): void {
  const counts = _CountApplicationsInPrimStack(prim)
  if (counts.size === 0) {
    return
  }

  const composed = new Set<string>()
  for (const record of AuthorshipAPI.getAll(prim)) {
    composed.add(record.getName())
  }

  for (const [instanceName] of counts) {
    if (!composed.has(instanceName)) {
      result.push(new AuthorshipAPI(prim, prim.getStage(), instanceName))
    }
  }
}

// authorshipAPI.cpp:634-643
function _AppendDuplicateRecordsForPrim(prim: Prim, result: AuthorshipAPI[]): void {
  for (const [instanceName, count] of _CountApplicationsInPrimStack(prim)) {
    if (count > 1) {
      result.push(new AuthorshipAPI(prim, prim.getStage(), instanceName))
    }
  }
}

// TfToken operator<: lexicographic string comparison.
function _TokenCompare(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0
}

// SdfPath orders a prim before its descendants, so sorting by path also
// sorts ancestors first (authorshipAPI.cpp:645-656).
function _RecordCompare(lhs: AuthorshipAPI, rhs: AuthorshipAPI): number {
  const lhsPath = lhs.prim.path
  const rhsPath = rhs.prim.path
  if (lhsPath !== rhsPath) {
    return SdfPath.compare(SdfPath.fromString(lhsPath), SdfPath.fromString(rhsPath))
  }
  return _TokenCompare(lhs.getName(), rhs.getName())
}

type _AppendForPrimFn = (prim: Prim, result: AuthorshipAPI[]) => void

// authorshipAPI.cpp:661-688
function _GetAllOnStageImpl(stage: Stage | undefined, appendForPrim: _AppendForPrimFn): AuthorshipAPI[] {
  const result: AuthorshipAPI[] = []

  if (!stage) {
    _codingError('Invalid stage')
  }

  // TraverseAll() includes inactive and abstract prims.
  for (const path of stage.traverseAll()) {
    const prim = stage.getPrim(path)
    if (prim) appendForPrim(prim, result)
  }

  // Prims beneath a native instance are not visited above, so walk the
  // prototypes to reach records authored inside them.
  for (const prototype of stage.getPrototypes()) {
    for (const prim of PrimRange.fromPrim(prototype, PrimAllPrimsPredicate)) {
      appendForPrim(prim, result)
    }
  }

  result.sort(_RecordCompare)

  return result
}

// authorshipAPI.cpp:690-702
function _GetForPrimImpl(prim: Prim | undefined, appendForPrim: _AppendForPrimFn): AuthorshipAPI[] {
  const result: AuthorshipAPI[] = []

  if (!prim || !prim.isValid()) {
    _codingError('Invalid prim')
  }

  appendForPrim(prim, result)
  return result
}

